data_fx_pair_probe_abort_v1<-function(code){if(!is.character(code)||length(code)!=1L||!grepl("^(data|desktop)_fx_pair_probe_[a-z_]+$",code))code<-"data_fx_pair_probe_boundary_failed";stop(structure(list(message=code,call=NULL,code=code),class=c("spot_data_fx_pair_probe_error_v1","error","condition")))}
new_data_fx_pair_probe_service_v1<-function(project_root,context){
 root<-normalizePath(project_root,winslash="/",mustWork=TRUE);python<-Sys.which("python3");cli<-file.path(root,"scripts","desktop_fx_pair_probe.py");space<-runtime_data_space_path(context);if(!nzchar(python)||!file.exists(cli)||!dir.exists(space))data_fx_pair_probe_abort_v1("data_fx_pair_probe_service_invalid")
 ctx<-list(tenant_id=context$tenant_id,user_id=context$user_id,data_space_id=context$data_space_id,actor_id="market_worker",role="market_worker");previews<-new.env(hash=TRUE,parent=emptyenv());results<-new.env(hash=TRUE,parent=emptyenv())
 run<-function(command,payload){o<-suppressWarnings(system2(python,c("-B","-E","-s",shQuote(cli),command),stdout=TRUE,stderr=TRUE,input=as.character(jsonlite::toJSON(payload,auto_unbox=TRUE,null="null",digits=NA))));s<-attr(o,"status");if(is.null(s))s<-0L;p<-tryCatch(jsonlite::fromJSON(tail(o,1L),simplifyVector=FALSE),error=function(e)NULL);if(is.null(p)||s!=0L||!identical(p$status,"completed"))data_fx_pair_probe_abort_v1(if(is.null(p$code))"data_fx_pair_probe_boundary_failed"else p$code);p}
 preview<-function(candidate,source,target,direction,start,end,now){x<-run("preview",list(context=ctx,candidate=candidate,source_currency=source,target_currency=target,direction=direction,start_date=start,end_date=end,created_at_utc=now));ref<-paste0("fxpp_",substr(digest::digest(jsonlite::toJSON(x$trusted_preview,auto_unbox=TRUE,null="null"),algo="sha256",serialize=FALSE),1,32));x$public_preview$preview_ref<-ref;assign(ref,list(trusted=x$trusted_preview,public=x$public_preview,consumed=FALSE),previews);x$public_preview}
 execute<-function(public,confirmed){if(!isTRUE(confirmed)||is.null(public$preview_ref)||!exists(public$preview_ref,previews,inherits=FALSE))data_fx_pair_probe_abort_v1("data_fx_pair_probe_confirmation_required");x<-get(public$preview_ref,previews);if(x$consumed||!identical(x$public,public))data_fx_pair_probe_abort_v1("data_fx_pair_probe_preview_invalid");x$consumed<-TRUE;assign(public$preview_ref,x,previews);p<-public;p$preview_ref<-NULL;y<-run("apply",list(context=ctx,data_space_path=space,trusted_preview=x$trusted,public_preview=p,confirmed=TRUE));ref<-paste0("fxpr_",substr(y$trusted_result$result_fingerprint,1,32));assign(ref,y$trusted_result,results);y$public_result$result_ref<-ref;y$public_result}
 resolve_result<-function(ref){if(!exists(ref,results,inherits=FALSE))data_fx_pair_probe_abort_v1("data_fx_pair_probe_preview_invalid");get(ref,results)}
 structure(list(preview=preview,execute=execute,resolve_result=resolve_result,automatic_provider_access=FALSE,automatic_retry=FALSE,fx_history_write=FALSE,canonical_write=FALSE),class=c("spot_data_fx_pair_probe_service_v1","list"))
}
